/* ═══════════════════════════════════════════════════════════════
   هنصلحلك — نظام الأيقونات المركزي (Icon System) — V7
   ───────────────────────────────────────────────────────────────
   V7 — إضافات فوق V6 (بدون حذف أو تغيير أي أيقونة موجودة):
   • st-arrived : مقدم الخدمة وصل
   • st-quote   : مطلوب موافقة العميل على السعر
   • st-failed  : تعذر تنفيذ الخدمة
   • تحديث STATUS_ICON ليطابق FLOW الجديد (12 حالة).
   • توافق خلفي كامل: كل الأسماء والأسماء البديلة (aliases) من V6 ما زالت موجودة.

   • شبكة موحدة 24×24، وزن خط موحد، أطراف مستديرة، زوايا بنصف قطر متقارب.
   • كل أيقونة طبقات: f (تعبئة ناعمة) + b (الهيكل — لون النص) + s (تفصيل معدني فضي)
     + a (لمسة Neon — اللون المميز للحالة). الأيقونة مقروءة بدون اللون والتأثيرات.
   • الحركة: كل أيقونة لها «شخصية حركة» (mo) تُنفّذ بـ transform/opacity فقط.
   • التوافق: P و ic(name, cls) كما كانت — كل الأسماء القديمة ما زالت تعمل.
   • الدوال: icp (أيقونة داخل لوحة)، icCat، icItem، icProb، icStatus، starsHtml.
   ═══════════════════════════════════════════════════════════════ */
'use strict';

const ICON_DEFS = {};
const ICON_ALIAS = {};
/* X(name, {f,b,s,a,mo}) — تعريف أيقونة */
const X = (n, o) => { ICON_DEFS[n] = o; };
const AL = (a, n) => { ICON_ALIAS[a] = n; };

/* مساعدات رسم صغيرة */
const _p = (d, c) => `<path d="${d}"${c ? ` class="${c}"` : ''}/>`;
const _c = (x, y, r, c) => `<circle cx="${x}" cy="${y}" r="${r}"${c ? ` class="${c}"` : ''}/>`;
const _r = (x, y, w, h, rx, c) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}"${c ? ` class="${c}"` : ''}/>`;
const _g = (c, inner, t) => `<g class="${c}"${t ? ` transform="${t}"` : ''}>${inner}</g>`;
/* نقطة (طول صفري بأطراف مستديرة) */
const _d = (x, y) => `<path d="M${x} ${y}v.01"/>`;
/* ترس بأسنان: مضلع مولّد */
const _gear = (cx, cy, ro, ri, n) => {
  let d = ''; const step = Math.PI * 2 / n, t = step * .2;
  for (let k = 0; k < n; k++) {
    const a = k * step - Math.PI / 2, pts = [[ri, a - step * .5 + t], [ro, a - t], [ro, a + t], [ri, a + step * .5 - t]];
    pts.forEach(([r, an], i) => { d += (k === 0 && i === 0 ? 'M' : 'L') + (cx + r * Math.cos(an)).toFixed(2) + ' ' + (cy + r * Math.sin(an)).toFixed(2); });
  }
  return `<path d="${d}Z"/>`;
};

