for (const n of Object.keys(LUCIDE_ICONS)) ICON_DEFS[n] = { b: LUCIDE_ICONS[n], mo: '' };

/* ───────────────────────── 9) طبقة التشغيل ───────────────────────── */
const _build = n => {
  const k = ICON_ALIAS[n] || n, d = ICON_DEFS[k]; if (!d) return null;
  return { k, mo: d.mo || '', html: (d.f ? `<g class="if">${d.f}</g>` : '') + (d.b ? `<g class="ib">${d.b}</g>` : '') + (d.s ? `<g class="im">${d.s}</g>` : '') + (d.a ? `<g class="ia">${d.a}</g>` : '') };
};
const _cache = {};
const P = new Proxy({}, { get: (_, n) => { if (typeof n !== 'string') return ''; const c = _cache[n] || (_cache[n] = _build(n)); return c ? c.html : ''; }, has: (_, n) => !!(ICON_ALIAS[n] || ICON_DEFS[n]) });
const ic = (n, cls = '') => { const c = _cache[n] || (_cache[n] = _build(n)); return `<svg class="i ${cls}" viewBox="0 0 24 24" data-m="${c ? c.mo : ''}" aria-hidden="true" focusable="false">${c ? c.html : ''}</svg>`; };
const icp = (n, kind = 'dev', cls = '') => { const ph = kind === 'dev' && typeof icImg === 'function' ? icImg(n) : ''; return ph ? `<span class="ip ${kind} ph ${cls}">${ph}</span>` : `<span class="ip ${kind} ${cls}">${ic(n)}</span>`; };
const icExists = n => !!(ICON_ALIAS[n] || ICON_DEFS[n]);

const icCat = id => icExists('c-' + id) ? 'c-' + id : 'p-service';

/* V10 photo icons (owner artwork, 2026-11-15): category and item icons rendered as images from
   assets/icons/svc/<group>/<name>.webp. Only category ('c-<cat>') and item ('d-<slug>') names have photos; every other
   icon (UI, status, problems) stays a line SVG. Pages live at apps/<app>/index.html, hence the ../../ base. */
const ICON_PHOTO_BASE = '../../assets/icons/svc/';
const ICON_PHOTO_ITEMS = {
  electric: ['wiring', 'dist-board', 'switches', 'lighting', 'fans', 'elec-heaters', 'electrical-devices', 'other-electric'],
  plumbing: ['faucets', 'sinks', 'toilet', 'siphon', 'heaters-plumb', 'pipes', 'water-tanks', 'pumps', 'sewage', 'other-plumbing'],
  carpentry: ['doors', 'windows', 'wardrobes', 'kitchens', 'chairs-tables', 'hinges-locks', 'assemble', 'other-carpentry'],
  painting: ['room', 'full-apartment', 'facades', 'ceilings', 'damp', 'cracks', 'wallpaper', 'decor-paint', 'other-painting'],
  cars: ['engine', 'brakes', 'battery', 'car-electric', 'car-ac', 'tires', 'gearbox', 'suspension', 'oil-change', 'towing', 'other-car'],
  cleaning: ['post-finishing', 'apartments', 'offices', 'carpets', 'mattresses', 'kitchens-clean', 'bathrooms', 'tanks-clean', 'villas', 'other-cleaning'],
  appliances: ['fridge', 'washer-auto', 'washer-semi', 'ac', 'heater-electric', 'heater-gas', 'dishwasher', 'deep-freezer', 'microwave', 'cooker', 'hood', 'other-appliance']
};
/* items without their own artwork reuse the closest one */
const ICON_PHOTO_ALIAS = { cables: 'electric/wiring', furniture: 'carpentry/chairs-tables', sofas: 'cleaning/other-cleaning' };
const ICON_PHOTOS = (() => {
  const m = {};
  for (const [g, list] of Object.entries(ICON_PHOTO_ITEMS)) { m['c-' + g] = 'home/' + g; for (const s of list) m['d-' + s] = g + '/' + s; }
  for (const [s, p] of Object.entries(ICON_PHOTO_ALIAS)) m['d-' + s] = p;
  return m;
})();
/* an image published from the Admin Center (HSSiteContent) overrides the bundled artwork */
const icPhoto = n => { const o = typeof globalThis !== 'undefined' && globalThis.HSSiteContent && globalThis.HSSiteContent.iconUrl(n); return o || (ICON_PHOTOS[n] ? ICON_PHOTO_BASE + ICON_PHOTOS[n] + '.webp' : ''); };
/* <img> for a photo icon, or '' when the name has none (callers then fall back to the SVG icon). Decorative: alt="". */
const icImg = (n, cls = '') => { const src = icPhoto(n); return src ? `<img class="iph ${cls}" src="${src}" alt="" aria-hidden="true" loading="lazy" decoding="async" draggable="false" width="112" height="112">` : ''; };
const icItem = (item, catId) => { const s = item && (item.slug || String(item.id || '').split('/').pop()); return s && icExists('d-' + s) ? 'd-' + s : icCat(catId || (item && item.cat)); };
const PROB_RULES = [
  [/^other$/, 'dots'],
  [/gas-smell|pilot|no-ignition|burner|knobs|flue|gas-refill/, 'p-gas'],
  [/igniter|spark|short|hot-plug/, 'p-spark'],
  [/smell|mold|smoke/, 'p-smell'],
  [/leak|burst|overflow|seal|float|drip|water-test/, 'p-leak'],
  [/no-power|main-off|trips|breaker|rcd|socket-dead|auto-cut|no-supply|power-loss|add-breaker/, 'p-power-off'],
  [/overheat/, 'p-overheat'],
  [/no-cooling|no-freeze|freezer-no|ice-buildup|thermostat|weak$/, 'p-no-cool'],
  [/no-heat|low-heat|element|^heater$|plate/, 'p-no-heat'],
  [/clog|drain|manhole|jetting|siphon/, 'p-clog'],
  [/noise|squeal|loud|unusual/, 'p-noise'],
  [/flicker|bulb-out|light|dimming|driver/, 'p-flicker'],
  [/pressure|weak-flow|weak-suction|no-pressure|low-pressure/, 'p-pressure'],
  [/weak-airflow/, 'p-weak'],
  [/vibration|wobble|slip|hard-shift|auto-jerk|pull|steering|ball-joints|uneven-wear|balance|pedal|shock/, 'p-vibration'],
  [/motor|compressor|spin|no-start|wont-start|alternator|belt|^no-water-intake$|^fan/, 'p-motor'],
  [/dead|jump-start|terminal/, 'p-dead'],
  [/board|timer|stabilizer|ups$|sensors|dashboard|warning|fuses|central-lock|control|windows$|lights$|intercom|doorbell/, 'p-board'],
  [/remote|screen|buttons/, 'p-remote'],
  [/wont-close|jammed|lock|latch|sag|hinge|door|rail|handle|stuck|gasket/, 'p-jam'],
  [/crack|corner|salt|damp|plaster/, 'd-cracks'],
  [/broken|glass|leg|cabinet|countertop|drawer|frame|^bed$|table|damaged|shelf|fabric|repolish|custom/, 'p-broken'],
  [/replace|change|remove|pads|switch-broken|flush|seat|tank|filter|dryer|extension|grounding/, 'p-replace'],
  [/install|extend|new-|add-|rewire|ikea|bedroom|kitchen-units|desk|tv-unit|connect|quote|wiring|hidden|mixer|valve|clean-install|pickup|transport|service|full-service|oil|engine-oil|filters|gearbox-oil|gearbox/, 'p-install'],
  [/deep|move-|full$|garden|pool|periodic|daily|regular|sterilize|full-room$/, 'p-deep-clean'],
  [/stains|wash|moth|dust|grease|appliances|cabinets|limescale|grout|ground|roof$|floors|paint-stains|paint-polish/, 'p-clean'],
  [/repaint|color|touch-up|finish|stucco|gypsum|effects|accent|fade|peeling|cornice|ceiling|house-facade|building|scaffold|rental/, 'p-paint'],
  [/breakdown|accident|towing/, 'p-vehicle']
];
const icProb = (p, item, catId) => {
  if (!p) return 'p-diagnose';
  const s = p.slug || String(p.id || '').split('/').pop(), c = catId || p.cat;
  if (c === 'cleaning' && /^(stains|dust|grease|limescale|grout|floors|paint-stains|wash|moth|appliances|cabinets)$/.test(s)) return 'p-clean';
  if (c === 'cleaning' && s === 'sterilize') return 'p-sterilize';
  if (c === 'cleaning' && s === 'dust') return 'p-dust';
  if (c === 'cleaning' && /^(roof|ground|water-test)$/.test(s)) return 'd-tanks-clean';
  if (c === 'cars' && s === 'dead') return 'p-dead';
  if (c === 'cars' && /^(breakdown|accident|stuck|transport)$/.test(s)) return 'p-vehicle';
  if (c === 'painting' && /^(stains|peeling|fade|full-room|new-finish|touch-up)$/.test(s)) return 'p-paint';
  if (s === 'dead' || s === 'crack') return s === 'dead' ? 'p-power-off' : 'p-broken';
  for (const [re, n] of PROB_RULES) if (re.test(s)) return n;
  return 'p-diagnose';
};

/* ═════════ ربط الحالات (V7) ═════════
   كل حالة من حالات FLOW و ALT_STATUS لها أيقونة موجودة.
   - cancelled → st-cancelled
   - failed    → st-failed
   - quote     → st-quote
   - arrived   → st-arrived
   أي حالة غير معروفة → st-new (توافق خلفي)  */
const STATUS_ICON = {
  received:'st-new', searching:'st-search', sent:'st-sent',
  accepted:'st-accepted', scheduled:'st-sched',
  enroute:'st-enroute', arrived:'st-arrived', started:'st-working',
  quote:'st-quote', completed:'st-done', closed:'st-closed',
  cancelled:'st-cancelled', failed:'st-failed',
  dispute:'st-dispute', complaint:'st-dispute'
};
const icStatus = s => STATUS_ICON[s] || 'st-new';

const starsHtml = n => { n = Math.round(n || 0); let o = ''; for (let k = 1; k <= 5; k++) o += `<svg class="i star ${k <= n ? 'on' : ''}" viewBox="0 0 24 24" aria-hidden="true"><g class="ib">${ICON_DEFS.star.b.replace(' class="mv"', '')}</g></svg>`; return `<span class="stars-svg" role="img" aria-label="${n} من 5">${o}</span>`; };
const SEC_ICON = { bolt: 'c-electric', tap: 'c-plumbing', saw: 'c-carpentry', roller: 'c-painting', car: 'c-cars', broom: 'c-cleaning', sparkle: 'c-cleaning', washer: 'c-appliances', plug: 'c-appliances' };
const icSec = n => SEC_ICON[n] || n;